const channels = [
  {handle: 'Akfon_DE', country: '🇩🇪 آلمان'},
  {handle: 'Hamburgdd', country: '🇩🇪 هامبورگ'},
  {handle: 'DivarFarsiHamburg', country: '🇩🇪 هامبورگ ۲'},
  {handle: 'DIWAR_ALMAN', country: '🇩🇪 دیوار آلمان'},
  {handle: 'Berlinetelat2', country: '🇩🇪 برلین'},
  {handle: 'Niaz4uk', country: '🇬🇧 لندن'},
  {handle: 'divar_estanbul', country: '🇹🇷 استانبول'},
  {handle: 'walcad', country: '🇨🇦 ونکوور'},
  {handle: 'omanex', country: '🇴🇲 عمان'},
  {handle: 'iranian_uae', country: '🇦🇪 دبی'}
];
return channels.map(c => ({json: c}));

const html = $input.first().json.data || '';
const handle = $('لیست ۱۰ دیوار تلگرامی خارج').item.json.handle;
const country = $('لیست ۱۰ دیوار تلگرامی خارج').item.json.country;

const filters = {
  digital: ['موشن دیزاینر', 'طراحی سایت', 'گرافیک', 'ادمین', 'فروش بین‌الملل', 'تدریس', 'آموزش زبان', 'آیلتس', 'bewerbung', 'ausbildung', 'رزومه', 'روانشناس', 'مشاوره', 'تراپی', 'سئو', 'فال قهوه'],
  housing_makler: ['مکلر', 'makler', 'دنبال خونه', 'نیازمند خانه', 'اجاره گرم', 'وارم میته', 'ملد', 'anmeldung', 'هم اتاقی', 'هم‌خانه'],
  luggage_cargo: ['بار مجاز', 'قبول مدارک', 'کیلو', 'مسافر', 'قبول دارو', 'پرواز تهران', 'فریت بار', 'زعفران', 'صنایع دستی'],
  legal_exchange: ['وکیل', 'وکالت', 'ثبت شرکت', 'وام شخصی', 'سرمایه گذار', 'حواله', 'صرافی', 'ریال عمان']
};

const regex = /<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/g;
let m;
const hits = [];
while ((m = regex.exec(html)) !== null) {
  const text = m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const low = text.toLowerCase();
  for (const [cat, kws] of Object.entries(filters)) {
    if (kws.some(k => low.includes(k))) {
      const contacts = text.match(/@[A-Za-z0-9_]{4,}|\+?\d[\d\s\-]{8,14}\d/g) || [];
      hits.push({json: {country, handle, category: cat, text: text.slice(0, 260), contacts: contacts.slice(0, 3)}});
      break;
    }
  }
}
return hits.slice(0, 10);
